<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
final class CustomerAttribution extends Model{use HasUuids;protected$fillable=['party_id','partner_id','origin_type','terms_version','effective_from','effective_until','status','evidence_reference','recorded_by'];protected function casts():array{return['effective_from'=>'datetime','effective_until'=>'datetime'];}public function party():BelongsTo{return$this->belongsTo(Party::class);}public function partner():BelongsTo{return$this->belongsTo(Partner::class);}public function recorder():BelongsTo{return$this->belongsTo(User::class,'recorded_by');}public function disputes():HasMany{return$this->hasMany(AttributionDispute::class,'attribution_id');}}
